  /* Weekday → deity of worship (popular devotional reckoning, vāra index 0 = Sunday).
     Distinct from the graha (planetary) lord in the pañcāṅga engine. */
  const stotraTypes = ["Stotra","Aṣṭakam","Pañcaratnam","Ṣaṭkam","Bhujaṅgam","Daṇḍakam","Cālīsā","Stuti","Mānasa Pūjā","Suprabhātam","Sūktam","Kavacam","Aṣṭottara","Sahasranāma"];

  /* ---- Form / avatāra invoked ----
     A second axis within each deity: the specific form or aspect the hymn
     addresses (Durgā vs Lalitā vs Annapūrṇā within Devī; Kṛṣṇa vs Rāma within
     Viṣṇu). Defaults to the deity's own name; only meaningful overrides listed.
     `forms` declares display order per deity (others append alphabetically). */
  const stotraForm = {
    // Devī
    "mahishasura":"Durgā", "d-devikavacham":"Durgā", "d-argala":"Durgā", "d-kilaka":"Durgā",
    "d-saptashloki":"Durgā", "d-ashtottara":"Durgā", "d-durgachalisa":"Durgā",
    "d-lalitasahasra":"Lalitā", "d-saundaryalahari":"Lalitā", "d-lalitatrishati":"Lalitā",
    "annapurna":"Annapūrṇā", "d-shyamala":"Śyāmalā", "d-bhavani":"Bhavānī",
    // Viṣṇu
    "madhurashtakam":"Kṛṣṇa", "bhaja-govindam":"Kṛṣṇa", "achyutashtakam":"Kṛṣṇa",
    "v-govindashtakam":"Kṛṣṇa", "v-mukundamala":"Kṛṣṇa", "v-krishnashtakam":"Kṛṣṇa",
    "v-yamunashtakam":"Kṛṣṇa", "v-gitadhyanam":"Kṛṣṇa",
    "v-ramaraksha":"Rāma", "v-suprabhatam":"Veṅkaṭeśa", "v-ranganatha":"Raṅganātha",
    "v-narayanasukta":"Nārāyaṇa", "v-dashavatara":"Daśāvatāra",
    // Śiva
    "s-kalabhairava":"Kālabhairava", "s-dakshinamurti":"Dakṣiṇāmūrti",
    // Lakṣmī
    "mahalakshmi-ashtakam":"Mahālakṣmī", "l-ashtalakshmi":"Aṣṭalakṣmī",
    "l-kamala":"Kamalā", "l-vaibhava":"Vaibhava Lakṣmī", "l-nrisimhakaravalamba":"Lakṣmīnṛsiṃha",
    // Gaṇeśa
    "g-mahaganapati":"Mahāgaṇapati",
    // Hanumān
    "h-panchamukha":"Pañcamukha",
  };
  const formOrder = {
    devi: ["Devī","Durgā","Lalitā","Annapūrṇā","Bhavānī","Śyāmalā"],
    vishnu: ["Viṣṇu","Kṛṣṇa","Rāma","Nārāyaṇa","Veṅkaṭeśa","Raṅganātha","Daśāvatāra"],
    shiva: ["Śiva","Kālabhairava","Dakṣiṇāmūrti"],
    lakshmi: ["Lakṣmī","Mahālakṣmī","Aṣṭalakṣmī","Kamalā","Lakṣmīnṛsiṃha","Vaibhava Lakṣmī"],
    ganesha: ["Gaṇeśa","Mahāgaṇapati"],
    hanuman: ["Hanumān","Pañcamukha"],
  };
  { const dn = Object.fromEntries(deities.map(d => [d.id, d.name]));
    stotras.forEach(s => { s.form = stotraForm[s.id] || dn[s.deity]; }); }
  const weekdayDeity = ["surya", "shiva", "hanuman", "ganesha", "vishnu", "lakshmi", "devi"];
  function deityForDay(date) { return (date || new Date()).getDay(); } // returns 0..6
  function todayDeity(date) { return deities.find(d => d.id === weekdayDeity[(date || new Date()).getDay()]); }

  return { collections, texts, daily, reader, gitaChapters, UNIT, tocFor, toDeva, panchanga, festivals,
           deities, stotras, stotraTypes, formOrder, weekdayDeity, todayDeity };
